import type { BankQuestion } from "@/lib/bank";

/** Rotational Motion (Physics (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-rotational-motion-1","question":"The SI unit of moment of inertia is:","options":["kg m","kg m²","N m","kg m/s"],"answer":1,"explanation":"I = Σmr², so its unit is kg m². N m is the unit of torque and kg m/s of linear momentum.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-rotational-motion-2","question":"The angular momentum of a rigid body rotating about a fixed axis with angular velocity ω and moment of inertia I is:","options":["Iω","Iω²/2","Iα","ω/I"],"answer":0,"explanation":"L = Iω, the rotational analogue of p = mv. Iα is torque and ½Iω² is rotational kinetic energy.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-rotational-motion-3","question":"The moment of inertia of a thin ring of mass M and radius R about an axis through its centre perpendicular to its plane is:","options":["MR²/2","2MR²/5","MR²","2MR²/3"],"answer":2,"explanation":"Every element of a ring is at distance R from the axis, so I = MR². MR²/2 is for a disc, 2MR²/5 for a solid sphere and 2MR²/3 for a hollow sphere.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-rotational-motion-4","question":"A uniform disc of mass 2 kg and radius 0.5 m rotates about its central axis at 4 rad/s. Its rotational kinetic energy is:","options":["4 J","1 J","8 J","2 J"],"answer":3,"explanation":"I = ½MR² = ½ × 2 × 0.25 = 0.25 kg m²; KE = ½Iω² = ½ × 0.25 × 16 = 2 J.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-rotational-motion-5","question":"The moment of inertia of a uniform thin rod of mass M and length L about an axis perpendicular to the rod through one end is:","options":["ML²/12","ML²/3","ML²/2","ML²/4"],"answer":1,"explanation":"Parallel-axis theorem: I_end = I_cm + M(L/2)² = ML²/12 + ML²/4 = ML²/3.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-rotational-motion-6","question":"A force of 10 N is applied tangentially at a distance of 2 m from the axis of a wheel whose moment of inertia is 4 kg m². The angular acceleration produced is:","options":["20 rad/s²","2.5 rad/s²","10 rad/s²","5 rad/s²"],"answer":3,"explanation":"τ = rF = 2 × 10 = 20 N m; α = τ/I = 20/4 = 5 rad/s².","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-rotational-motion-7","question":"A spinning ice skater pulls her arms in so that her moment of inertia halves. Her rotational kinetic energy:","options":["halves","stays the same","becomes four times","doubles"],"answer":3,"explanation":"No external torque, so L = Iω is constant and ω doubles. KE = L²/2I doubles when I halves; the extra energy comes from the work her muscles do pulling the arms in.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-8","question":"The acceleration due to gravity at a height equal to the radius of the Earth above its surface is (g = value at the surface):","options":["g/2","g/4","g/8","g/16"],"answer":1,"explanation":"g_h = GM/(R + h)² = GM/(2R)² = g/4. Halving (g/2) is a common slip that ignores the inverse-square law.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-rotational-motion-9","question":"A planet has twice the radius of the Earth and the same mean density. If the escape velocity from the Earth is 11.2 km/s, that from the planet is:","options":["11.2 km/s","5.6 km/s","44.8 km/s","22.4 km/s"],"answer":3,"explanation":"v_e = √(2GM/R) and M = (4/3)πR³ρ, so v_e ∝ R√ρ. Doubling R at the same density doubles v_e: 22.4 km/s.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-rotational-motion-10","question":"For a solid sphere rolling without slipping on a horizontal surface, the fraction of its total kinetic energy that is rotational is:","options":["2/7","5/7","2/5","1/2"],"answer":0,"explanation":"KE_rot/KE_total = (I/MR²)/(1 + I/MR²) = (2/5)/(7/5) = 2/7. (For a ring it is 1/2, for a disc 1/3.)","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-11","question":"A ring, a disc, a solid sphere and a hollow sphere, all of the same mass and radius, are released together from the top of a rough incline and roll without slipping. The first to reach the bottom is the:","options":["ring","disc","solid sphere","hollow sphere"],"answer":2,"explanation":"a = g sinθ/(1 + I/MR²); the solid sphere has the smallest I/MR² (2/5), so it accelerates fastest. Order: solid sphere, disc (1/2), hollow sphere (2/3), ring (1). The mass and radius do not matter.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-12","question":"A solid cylinder rolls without slipping down a 30° incline (g = 10 m/s²). Its acceleration is:","options":["5 m/s²","10/3 m/s²","20/7 m/s²","5/2 m/s²"],"answer":1,"explanation":"a = g sinθ/(1 + I/MR²) = (10 × 0.5)/(1 + 1/2) = 5/(3/2) = 10/3 m/s². (20/7 would be a solid sphere, 5/2 a ring.)","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-13","question":"The moment of inertia of a uniform circular disc of mass M and radius R about one of its diameters is:","options":["MR²/2","MR²/8","MR²","MR²/4"],"answer":3,"explanation":"Perpendicular-axis theorem: I_z = I_x + I_y with I_x = I_y by symmetry, so I_diameter = (MR²/2)/2 = MR²/4.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-14","question":"A 2 kg particle moves at a constant 3 m/s along the line y = 4 m parallel to the x-axis. Its angular momentum about the origin is:","options":["12 kg m²/s","24 kg m²/s","0","6 kg m²/s"],"answer":1,"explanation":"L = mv × (perpendicular distance of the line from the origin) = 2 × 3 × 4 = 24 kg m²/s, constant in magnitude and direction even though the path is straight.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-15","question":"The angular momentum of a body about an axis varies with time as L = 3t² (SI units). The torque acting on it at t = 2 s is:","options":["6 N m","24 N m","3 N m","12 N m"],"answer":3,"explanation":"τ = dL/dt = 6t = 12 N m at t = 2 s.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-16","question":"A satellite orbits a planet in a circle of radius r with period T. Another satellite orbits the same planet at radius 4r. Its period is:","options":["4T","2√2 T","8T","2T"],"answer":2,"explanation":"Kepler's third law: T² ∝ r³, so T' = T × 4^(3/2) = 8T.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-17","question":"A uniform rod of length 4 m and mass 10 kg is hinged at one end and held horizontal by a vertical string attached 2.5 m from the hinge (g = 10 m/s²). The tension in the string is:","options":["80 N","100 N","50 N","60 N"],"answer":0,"explanation":"Taking torques about the hinge: T × 2.5 = 100 × 2 (weight acts at the centre, 2 m from the hinge), so T = 80 N. The hinge supplies the remaining 20 N.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-18","question":"A wheel starts from rest with uniform angular acceleration. The ratio of the angle turned in the first 5 s to the angle turned in the next 5 s is:","options":["1:2","1:4","1:3","2:3"],"answer":2,"explanation":"θ = ½αt²: in 5 s, θ₁ = 12.5α; in 10 s, 50α; so the next 5 s contribute 37.5α. Ratio = 12.5 : 37.5 = 1 : 3, exactly like the odd-number rule for linear motion.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-19","question":"A solid sphere is released on a rough incline of angle 45°. The minimum coefficient of friction for it to roll without slipping is:","options":["2/5","1/3","5/7","2/7"],"answer":3,"explanation":"For rolling, friction f = (I/MR²) mg sinθ/(1 + I/MR²) = (2/7) mg sinθ must not exceed μ mg cosθ, so μ_min = (2/7) tanθ = 2/7 at 45°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-20","question":"How many of the following statements are correct?\n(A) The angular momentum of a particle moving with uniform velocity, about a point not on its line of motion, is non-zero and constant.\n(B) Torque and angular momentum are axial vectors.\n(C) The moment of inertia of a body depends on the choice of axis.\n(D) For a body rolling without slipping, the point of contact is instantaneously at rest.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: L = mvd is constant for a straight-line motion (no torque); torque and angular momentum are defined by cross products and so are axial vectors; I changes with the axis (parallel-axis theorem); pure rolling means v_cm = ωR and the contact point has zero velocity.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-21","question":"A uniform rod of mass 3 kg and length 2 m lies on a smooth table, pivoted at its centre. A 1 kg particle moving at 6 m/s perpendicular to the rod strikes one end and sticks to it. The angular speed of the system just after the collision is:","options":["3 rad/s","2 rad/s","6 rad/s","1.5 rad/s"],"answer":0,"explanation":"Angular momentum about the pivot is conserved: 1 × 6 × 1 = (ML²/12 + m × 1²) ω = (3 × 4/12 + 1) ω = 2ω, so ω = 3 rad/s. Linear momentum is not conserved because the pivot exerts an impulsive force.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-22","question":"Masses of 4 kg and 2 kg hang from a string that passes over a pulley which is a uniform disc of mass 4 kg; the string does not slip on the pulley (g = 10 m/s²). The acceleration of the masses is:","options":["10/3 m/s²","2 m/s²","2.5 m/s²","5 m/s²"],"answer":2,"explanation":"With a massive pulley, a = (m₁ − m₂)g/(m₁ + m₂ + I/R²) and I/R² = M/2 = 2 kg: a = 20/(4 + 2 + 2) = 2.5 m/s². Ignoring the pulley gives 10/3 m/s². The tensions on the two sides are different (30 N and 25 N).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-23","question":"Assuming the Earth to be a uniform sphere, the value of g at a small depth d below the surface equals the value at a small height h above the surface when:","options":["d = h","d = h/2","d = 2h","d = 4h"],"answer":2,"explanation":"At depth d, g_d = g(1 − d/R); at small height h, g_h ≈ g(1 − 2h/R). Equating gives d = 2h.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-24","question":"The minimum energy required to launch a satellite of mass m from the Earth's surface into a circular orbit of radius 2R (R = radius of the Earth, g = surface gravity) is:","options":["mgR/2","3mgR/4","mgR/4","mgR"],"answer":1,"explanation":"Initial energy = −GMm/R = −mgR; orbital total energy = −GMm/(2 × 2R) = −mgR/4. Required energy = −mgR/4 − (−mgR) = 3mgR/4. Using only the change in potential energy (mgR/2) forgets the orbital kinetic energy.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-25","question":"A solid sphere rolls without slipping down from rest through a vertical height of 7 m (g = 10 m/s²). The speed of its centre at the bottom is:","options":["√140 m/s","7 m/s","√70 m/s","10 m/s"],"answer":3,"explanation":"mgh = ½mv²(1 + 2/5) = (7/10)mv², so v = √(10gh/7) = √(10 × 10 × 7/7) = 10 m/s. √140 m/s would be the result for sliding without friction.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-26","question":"Assertion (A): A solid sphere and a hollow sphere of the same mass and radius are released together on a rough incline; the solid sphere reaches the bottom first.\nReason (R): The body with the smaller moment of inertia has the larger acceleration a = g sinθ/(1 + I/MR²) when rolling without slipping.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"I/MR² is 2/5 for the solid and 2/3 for the hollow sphere, so the solid sphere's acceleration (5g sinθ/7) exceeds the hollow sphere's (3g sinθ/5); R is exactly the reason for A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-27","question":"A uniform rod of length 1.5 m is hinged at one end and released from rest in the horizontal position (g = 10 m/s²). The linear acceleration of its free end at the instant of release is:","options":["10 m/s²","7.5 m/s²","15 m/s²","5 m/s²"],"answer":2,"explanation":"α = τ/I = (mg × L/2)/(mL²/3) = 3g/2L = 10 rad/s²; the free end has a = αL = 15 m/s², greater than g — which is why a coin placed near the free end loses contact.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-28","question":"Match each body (axis through its centre of mass as stated) with its moment of inertia:\n(a) Solid sphere about a diameter\n(b) Hollow sphere about a diameter\n(c) Disc about a diameter\n(d) Rod about a perpendicular axis through its centre\n1. (2/5)MR²  2. (2/3)MR²  3. MR²/4  4. ML²/12","options":["a-2, b-1, c-3, d-4","a-1, b-2, c-3, d-4","a-1, b-2, c-4, d-3","a-2, b-1, c-4, d-3"],"answer":1,"explanation":"Solid sphere (2/5)MR², hollow sphere (2/3)MR², disc about a diameter MR²/4 (half of MR²/2 by the perpendicular-axis theorem) and rod about its centre ML²/12.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-29","question":"A ring is placed on a rough horizontal surface with linear velocity v₀ and no spin. When it finally rolls without slipping, the velocity of its centre is:","options":["v₀/2","2v₀/3","v₀/3","v₀"],"answer":0,"explanation":"Friction acts at the contact point, so angular momentum about the contact point is conserved: m v₀ R = (mR² + mR²) ω = 2mR v, giving v = v₀/2. (For a solid sphere the answer would be 5v₀/7.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-30","question":"A uniform disc of mass 2 kg rotates freely about its central axis. A 1 kg particle is gently placed on its rim and sticks to it. The fraction of the initial rotational kinetic energy lost is:","options":["1/3","1/4","2/3","1/2"],"answer":3,"explanation":"I₁ = ½ × 2R² = R²; I₂ = R² + 1 × R² = 2R². L is conserved, so KE = L²/2I halves: fraction lost = 1/2.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-31","question":"A force of 5 N acts perpendicular to a spanner at a distance of 0.4 m from the axis of the bolt. The torque about the axis is:","options":["5.4 N m","12.5 N m","2 N m","0.08 N m"],"answer":2,"explanation":"τ = rF sin90° = 0.4 × 5 = 2 N m.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-32","question":"The moment of inertia of a uniform disc of mass M and radius R about an axis tangent to its rim and perpendicular to its plane is:","options":["MR²/2","2MR²","5MR²/4","3MR²/2"],"answer":3,"explanation":"By the parallel-axis theorem, I = MR²/2 + MR² = 3MR²/2. 5MR²/4 is the value about a tangent lying in the plane of the disc.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-33","question":"A ring of mass 2 kg rolls without slipping with its centre moving at 3 m/s. Its total kinetic energy is:","options":["9 J","36 J","18 J","13.5 J"],"answer":2,"explanation":"For a ring I = MR², so K = ½Mv² + ½MR²(v/R)² = Mv² = 2 × 9 = 18 J. 9 J counts only translation.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-rotational-motion-34","question":"A disc rotates freely about its axis with angular speed ω. An identical disc, initially at rest, is gently placed on it coaxially and the two rotate together. The common angular speed is:","options":["ω/4","2ω","ω/2","ω"],"answer":2,"explanation":"Angular momentum is conserved and the moment of inertia doubles: Iω = 2Iω', so ω' = ω/2. Half the kinetic energy is lost to friction between the discs.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-rotational-motion-35","question":"The radius of gyration of a uniform solid sphere of radius R about a tangent to its surface is:","options":["√(3/2) R","√(2/5) R","√(7/5) R","√(5/7) R"],"answer":2,"explanation":"I = 2MR²/5 + MR² = 7MR²/5 = Mk², so k = √(7/5) R. √(2/5) R is the value about a diameter.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-36","question":"A uniform rod 0.6 m long is hinged at one end and released from rest in the horizontal position (g = 10 m/s²). Its angular speed when it becomes vertical is:","options":["√10 rad/s","5 rad/s","10 rad/s","5√2 rad/s"],"answer":3,"explanation":"The centre falls L/2: mgL/2 = ½(mL²/3)ω², so ω = √(3g/L) = √(30/0.6) = √50 = 5√2 rad/s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-37","question":"A light string is wound on a uniform solid cylinder of mass 4 kg that can rotate freely about its fixed horizontal axis. A 2 kg block hangs from the free end of the string (g = 10 m/s²). The acceleration of the block is:","options":["20/3 m/s²","10 m/s²","5 m/s²","4 m/s²"],"answer":2,"explanation":"mg − T = ma and TR = (MR²/2)(a/R), so T = Ma/2. Then a = mg/(m + M/2) = 20/(2 + 2) = 5 m/s².","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-rotational-motion-38","question":"The moment of inertia of a thin uniform square plate of mass M and side a about one of its diagonals is:","options":["Ma²/3","Ma²/12","Ma²/6","Ma²/24"],"answer":1,"explanation":"About the axis through the centre perpendicular to the plate I = Ma²/6. By the perpendicular-axis theorem this equals the sum for the two diagonals, which are equal by symmetry, so each is Ma²/12.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-39","question":"A uniform solid cylinder of radius R is placed on a rough horizontal floor with its centre moving forward at v₀ and with a backspin of angular speed v₀/R. When it finally rolls without slipping, the velocity of its centre is:","options":["zero","v₀/3 forward","v₀/3 backward","v₀/2 forward"],"answer":1,"explanation":"Friction acts at the contact point, so angular momentum about that point is conserved: Mv₀R − (MR²/2)(v₀/R) = (3/2)MR v → Mv₀R/2 = (3/2)MRv → v = v₀/3, still forward.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-40","question":"A uniform cube rests on a rough horizontal floor. A gradually increasing horizontal force is applied at the middle of the top edge of one face, perpendicular to that face. The minimum coefficient of friction for the cube to topple before it slides is:","options":["0.5","1","1/√2","0.25"],"answer":0,"explanation":"About the front bottom edge, toppling begins when F·a = mg·a/2, i.e. F = mg/2. For no sliding until then, μmg ≥ mg/2, so μ ≥ 0.5.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-41","question":"How many of the following statements are correct?\n(A) The moment of inertia of a body depends on the position of the axis of rotation.\n(B) In rolling without slipping, the point of contact is momentarily at rest.\n(C) When a body rolls without slipping down an incline, friction dissipates part of its mechanical energy.\n(D) In rolling without slipping, the topmost point moves at twice the speed of the centre.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and D are correct. C is wrong: in pure rolling the contact point does not slip, so static friction does no work and mechanical energy is conserved. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-42","question":"A uniform rod of mass 3 kg and length 1.5 m hangs vertically from a frictionless hinge at its upper end. A 0.5 kg ball of clay moving horizontally at 12 m/s strikes the lower end and sticks to it. The angular speed of the rod just after impact is:","options":["4 rad/s","8/3 rad/s","2 rad/s","16/3 rad/s"],"answer":1,"explanation":"Angular momentum about the hinge is conserved (the hinge force has no torque about it): 0.5 × 12 × 1.5 = 9. I = ML²/3 + mL² = 2.25 + 1.125 = 3.375 kg m², so ω = 9/3.375 = 8/3 rad/s. Linear momentum is not conserved because of the hinge impulse.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-43","question":"A uniform solid cylinder rolls without slipping at 6 m/s towards a rough incline and rolls up it without slipping (g = 10 m/s²). The maximum vertical height it reaches is:","options":["2.7 m","3.6 m","1.8 m","2.52 m"],"answer":0,"explanation":"All the KE, ½mv²(1 + k²/R²) = ¾mv², becomes mgh: h = 3v²/4g = 3 × 36/40 = 2.7 m. 1.8 m ignores rotation, 3.6 m would be a ring and 2.52 m a solid sphere.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-44","question":"Assertion (A): If the polar ice caps melted completely, the length of the day would increase.\nReason (R): The water would spread towards the equator, increasing the Earth's moment of inertia, while its angular momentum stays constant.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: with L = Iω constant and I increased, ω decreases, so a day (2π/ω) becomes longer.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-rotational-motion-45","question":"A wheel rolls without slipping on level ground with its centre moving at speed v. The speed of a point on the rim that is at the same height as the centre is:","options":["√2 v","zero","v","2v"],"answer":0,"explanation":"That point has the translational velocity v (horizontal) plus the rotational velocity ωR = v (vertical); the resultant is √2 v. Equivalently, it is √2 R from the contact point, the instantaneous axis.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "phy-rotational-motion-46", "question": "Torque has the same dimensions as:", "options": ["linear momentum", "angular momentum", "work", "power"], "answer": 2, "explanation": "Torque = r × F has dimensions [ML²T⁻²], the same as work and energy, although torque is a vector and is never expressed in joules.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-rotational-motion-47", "question": "A body of mass 2 kg has a moment of inertia of 0.08 kg m² about an axis. Its radius of gyration about that axis is:", "options": ["0.2 m", "0.04 m", "0.4 m", "0.16 m"], "answer": 0, "explanation": "I = Mk², so k = √(0.08/2) = √0.04 = 0.2 m. 0.04 m is k², not k.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-rotational-motion-48", "question": "The moment of inertia of a uniform rod of mass M and length L about an axis perpendicular to it, passing through a point at L/4 from one end, is:", "options": ["ML²/12", "ML²/16", "ML²/3", "7ML²/48"], "answer": 3, "explanation": "The point is L/4 from the centre, so by the parallel-axis theorem I = ML²/12 + M(L/4)² = ML²(4 + 3)/48 = 7ML²/48.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-rotational-motion-49", "question": "A uniform disc of mass 2 kg and radius 0.2 m rotates about its central axis at 10 rad/s. Its angular momentum is:", "options": ["0.8 kg m²/s", "0.4 kg m²/s", "0.2 kg m²/s", "4 kg m²/s"], "answer": 1, "explanation": "L = Iω = ½MR²ω = ½ × 2 × 0.04 × 10 = 0.4 kg m²/s. 0.8 uses MR², the value for a ring.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-rotational-motion-50", "question": "A flywheel rotating at 300 rpm is brought to rest uniformly in 10 s. The number of revolutions it makes while stopping is:", "options": ["50", "25", "300", "15"], "answer": 1, "explanation": "300 rpm = 5 rev/s. With uniform deceleration the average rate is 2.5 rev/s, so it makes 2.5 × 10 = 25 revolutions. 50 forgets to average.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-rotational-motion-51", "question": "The moment of inertia of a thin uniform ring of mass M and radius R about one of its diameters is:", "options": ["MR²", "3MR²/2", "MR²/4", "MR²/2"], "answer": 3, "explanation": "By the perpendicular-axis theorem, I_d + I_d = I_z = MR², so I_d = MR²/2. MR²/4 is the corresponding result for a disc.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-rotational-motion-52", "question": "A force F = (3 i + 4 j) N acts at a point whose position vector is r = (i + 2 j) m. The torque about the origin is:", "options": ["−2 k N m", "2 k N m", "10 k N m", "11 k N m"], "answer": 0, "explanation": "τ = r × F = (x F_y − y F_x) k = (1 × 4 − 2 × 3) k = −2 k N m. Reversing the order of the cross product gives the sign error +2 k.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-53", "question": "A uniform rod of mass 2M and length 2L is bent at its midpoint into an L shape (a right angle). Its moment of inertia about an axis through the bend, perpendicular to the plane of the L, is:", "options": ["ML²/3", "4ML²/3", "2ML²/3", "ML²/6"], "answer": 2, "explanation": "Each arm has mass M and length L and rotates about its own end: ML²/3 each. Bending does not change each arm's distance from the axis, so I = 2ML²/3.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-54", "question": "A horizontal platform with moment of inertia 200 kg m² rotates freely at 1 rad/s about a vertical axis through its centre. A 50 kg man walks from the centre to a point 2 m from the axis. The new angular speed is:", "options": ["0.8 rad/s", "1 rad/s", "2 rad/s", "0.5 rad/s"], "answer": 3, "explanation": "No external torque, so angular momentum is conserved: 200 × 1 = (200 + 50 × 2²)ω, giving ω = 200/400 = 0.5 rad/s. Kinetic energy is not conserved here.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-rotational-motion-55", "question": "A ring and a disc of the same mass and radius are released from rest from the top of the same incline and roll without slipping. The ratio of the time taken by the ring to that taken by the disc to reach the bottom is:", "options": ["√3/2", "2/√3", "2", "√2"], "answer": 1, "explanation": "a = g sin θ/(1 + k²/R²), so t ∝ √(1 + k²/R²): ring √2 and disc √1.5. Ratio = √(2/1.5) = 2/√3 ≈ 1.15, so the ring is slower.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-56", "question": "A wheel starts from rest with an angular acceleration α = 6t rad/s², where t is in seconds. The angle through which it turns in the first 2 s is:", "options": ["12 rad", "24 rad", "8 rad", "6 rad"], "answer": 2, "explanation": "ω = ∫6t dt = 3t² and θ = ∫3t² dt = t³, so θ = 8 rad at t = 2 s. 12 rad treats the acceleration as constant at its final value.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-57", "question": "A horizontal force F is applied at the centre of a uniform disc of mass M resting on a rough horizontal floor, and the disc rolls without slipping. The friction force on the disc is:", "options": ["F/3, opposite to F", "F/3, along F", "2F/3, opposite to F", "zero"], "answer": 0, "explanation": "F − f = Ma and fR = ½MR²(a/R), so f = Ma/2. Then F = 3Ma/2, a = 2F/3M and f = F/3, pointing backwards to supply the torque that spins the disc.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-58", "question": "A uniform metre rule of mass 100 g is pivoted at its 40 cm mark. The mass that must be hung at the 10 cm mark to keep it horizontal is:", "options": ["25 g", "50 g", "33.3 g", "100 g"], "answer": 2, "explanation": "The rule's weight acts at the 50 cm mark, 10 cm from the pivot: 100 × 10 = m × 30, so m ≈ 33.3 g. 25 g uses 40 cm as the lever arm (measuring from the end).", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-rotational-motion-59", "question": "A solid sphere and a hollow sphere roll without slipping from rest down the same height. The ratio of their speeds at the bottom (solid : hollow) is:", "options": ["5 : √21", "√21 : 5", "1 : 1", "√7 : √5"], "answer": 0, "explanation": "v² = 2gh/(1 + k²/R²): solid 2gh/(7/5), hollow 2gh/(5/3). v_s/v_h = √((5/3)/(7/5)) = √(25/21) = 5/√21 ≈ 1.09, so the solid sphere is faster.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-60", "question": "A uniform rod of mass M and length L rests on a smooth horizontal table. A horizontal impulse J is given at one end, perpendicular to the rod. Immediately afterwards, the velocity of the other end is:", "options": ["J/M, along the impulse", "4J/M, along the impulse", "zero", "2J/M, opposite to the impulse"], "answer": 3, "explanation": "v_cm = J/M and Jℓ = Iω with ℓ = L/2: ω = (JL/2)/(ML²/12) = 6J/ML. The far end moves at v_cm − ωL/2 = J/M − 3J/M = −2J/M, i.e. 2J/M opposite to the impulse.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-rotational-motion-61", "question": "How many of the following statements are correct?\n(A) The angular momentum of a system is conserved if the net external torque on it is zero, even when external forces act.\n(B) A body can be in translational equilibrium without being in rotational equilibrium.\n(C) For a wheel rolling without slipping, the topmost point moves at twice the speed of the centre.\n(D) A force has a non-zero torque about an axis parallel to its line of action.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A (e.g. a central force), B (a couple gives zero net force but non-zero torque) and C are correct. D is wrong: a force parallel to an axis has zero torque about it. Three are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-rotational-motion-62", "question": "A light string wound round a uniform disc of mass 2 kg is pulled horizontally from the top of the disc with a force of 6 N, and the disc rolls without slipping on a rough horizontal floor. The acceleration of its centre and the friction on it are:", "options": ["2 m/s², 2 N backward", "4 m/s², 2 N forward", "3 m/s², zero", "4 m/s², 2 N backward"], "answer": 1, "explanation": "With friction f taken forward: F + f = Ma and (F − f)R = ½MR²(a/R), so F − f = Ma/2. Adding gives 2F = 1.5Ma, a = 4F/3M = 4 m/s², and f = Ma − F = 8 − 6 = 2 N, which comes out positive, so it points forward.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-rotational-motion-63", "question": "A 1 kg particle is projected at 20 m/s at 30° above level ground (g = 10 m/s²). Its angular momentum about the point of projection when it is at the highest point of its path is:", "options": ["100 kg m²/s", "50√3 kg m²/s", "50 kg m²/s", "200√3 kg m²/s"], "answer": 1, "explanation": "At the top the velocity is horizontal, u cos 30° = 10√3 m/s, and the height is H = (u sin 30°)²/2g = 5 m. L = m v H = 1 × 10√3 × 5 = 50√3 ≈ 86.6 kg m²/s.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-64", "question": "A yo-yo (a uniform disc of mass 3 kg) has its string wound round it, with the free end held fixed. It falls as the string unwinds vertically (g = 10 m/s²). The tension in the string is:", "options": ["20 N", "15 N", "30 N", "10 N"], "answer": 3, "explanation": "mg − T = ma and TR = ½MR²(a/R), so T = ma/2. Then mg = 3ma/2, a = 2g/3, and T = mg/3 = 10 N. 30 N would mean the disc does not accelerate.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-65", "question": "A uniform ladder 5 m long rests against a smooth vertical wall with its foot on a rough floor 3 m from the wall. The minimum coefficient of friction at the floor that prevents slipping is:", "options": ["3/8", "3/4", "3/5", "4/3"], "answer": 0, "explanation": "The top is 4 m high. Torques about the foot: N_wall × 4 = W × 1.5, so N_wall = 3W/8. Friction must equal N_wall while the floor's normal force is W, so μ ≥ 3/8.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-66", "question": "Assertion (A): When a body rolls without slipping on a rough horizontal surface (no other horizontal force), the friction force does no work on it.\nReason (R): The point of contact of the rolling body is instantaneously at rest.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: friction acts at the contact point, which has zero velocity, so its power F·v is zero and no energy is dissipated in pure rolling.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-67", "question": "Match the body rolling without slipping down an incline of angle θ (List I) with its acceleration (List II).\nList I: (P) ring; (Q) disc; (R) solid sphere; (S) hollow sphere.\nList II: (1) (1/2) g sin θ; (2) (2/3) g sin θ; (3) (3/5) g sin θ; (4) (5/7) g sin θ.", "options": ["P-1, Q-2, R-3, S-4", "P-2, Q-1, R-4, S-3", "P-1, Q-2, R-4, S-3", "P-1, Q-4, R-2, S-3"], "answer": 2, "explanation": "a = g sin θ/(1 + k²/R²) with k²/R² = 1, 1/2, 2/5 and 2/3, giving 1/2, 2/3, 5/7 and 3/5. So P-1, Q-2, R-4, S-3.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-rotational-motion-68", "question": "A concentric circular hole of radius R/2 is cut from a uniform disc of radius R. If the mass of the remaining annular disc is M, its moment of inertia about the central axis perpendicular to its plane is:", "options": ["15MR²/32", "MR²/2", "3MR²/8", "5MR²/8"], "answer": 3, "explanation": "For an annulus I = ½M(R₁² + R₂²) = ½M(R² + R²/4) = 5MR²/8. 15MR²/32 is the same result written in terms of the mass of the original full disc (4M/3).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-69", "question": "A uniform rod of mass 2 kg and length 1 m rotates on a smooth horizontal table at 4 rad/s about a vertical axis through one end. The horizontal force exerted on the rod by the pivot is:", "options": ["32 N", "16 N", "8 N", "zero"], "answer": 1, "explanation": "The pivot must supply the centripetal force on the centre of mass: F = Mω²(L/2) = 2 × 16 × 0.5 = 16 N, directed towards the axis. 32 N places the whole mass at the far end.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-70", "question": "A wheel with moment of inertia 2 kg m² spinning at 50 rad/s is brought to rest in 10 s by a constant frictional torque. The torque and the number of revolutions made while stopping are about:", "options": ["10 N m and 80 revolutions", "5 N m and 40 revolutions", "10 N m and 40 revolutions", "20 N m and 250 revolutions"], "answer": 2, "explanation": "α = 50/10 = 5 rad/s², so τ = Iα = 10 N m. θ = (ω₀/2)t = 250 rad = 250/2π ≈ 40 revolutions. 250 is the angle in radians, not revolutions.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-rotational-motion-71","question":"A particle at position r = (i + j + k) m has linear momentum p = (2i − j) kg m/s. Its angular momentum about the origin is:","options":["(i + 2j − 3k) kg m²/s","(i − 2j − 3k) kg m²/s","(−i − 2j + 3k) kg m²/s","(i + 2j + 3k) kg m²/s"],"answer":0,"explanation":"L = r × p = (r_y p_z − r_z p_y, r_z p_x − r_x p_z, r_x p_y − r_y p_x) = (0 + 1, 2 − 0, −1 − 2) = (1, 2, −3). Taking p × r instead reverses every sign.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-72","question":"The moment of inertia of a thin uniform rod of mass M and length L about an axis through its centre making an angle of 30° with the rod is:","options":["ML²/12","ML²/48","ML²/16","ML²/24"],"answer":1,"explanation":"Each element at distance x along the rod is x sin 30° from the axis, so I = (ML²/12) sin²30° = (ML²/12)(1/4) = ML²/48. ML²/24 uses sin 30° instead of sin²30°.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-73","question":"A wheel rotating at 300 rpm is driven by a constant torque of 10 N m. The power delivered by the torque at that instant is about:","options":["3000 W","50 W","314 W","31.4 W"],"answer":2,"explanation":"ω = 300 × 2π/60 = 10π rad/s, so P = τω = 10 × 10π ≈ 314 W. Multiplying the torque by the rpm (3000) forgets to convert to rad/s.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-74","question":"A uniform rod of mass M is hinged at one end and released from rest in the horizontal position. The force exerted by the hinge on the rod as it passes through the vertical position is:","options":["Mg","Mg/4","3Mg/2","5Mg/2"],"answer":3,"explanation":"Energy: Mg(L/2) = ½(ML²/3)ω², so ω² = 3g/L. At the vertical the torque is zero, so there is no tangential acceleration; the hinge supplies weight plus centripetal force: N = Mg + Mω²(L/2) = Mg + 3Mg/2 = 5Mg/2. Mg/4 is the hinge force at the moment of release.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-75","question":"A thin uniform wire of mass M and length L is bent into a circular ring. Its moment of inertia about a tangent to the ring lying in the plane of the ring is:","options":["3ML²/(8π²)","ML²/(8π²)","ML²/(2π²)","3ML²/(4π²)"],"answer":0,"explanation":"R = L/(2π). About a diameter I = MR²/2; the parallel-axis theorem gives MR²/2 + MR² = 3MR²/2 for a tangent in the plane, = 3ML²/(8π²). ML²/(2π²) (= 2MR²) is for a tangent perpendicular to the plane.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-76","question":"Three identical thin uniform rods, each of mass m and length a, form an equilateral triangle. The moment of inertia of the frame about an axis through its centroid perpendicular to its plane is:","options":["ma²/4","ma²/2","ma²/6","ma²"],"answer":1,"explanation":"Each rod's centre is at the in-radius a/(2√3) from the centroid. Per rod: ma²/12 + m(a²/12) = ma²/6; for three rods, ma²/2. ma²/6 is the value for just one rod.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-77","question":"A uniform rod of mass 3 kg and length 1 m rotates freely at 10 rad/s about a vertical axis through its centre on a smooth horizontal surface. Two beads of 0.5 kg each, initially at the centre, slide out along the rod to its two ends. The new angular speed is:","options":["2.5 rad/s","7.5 rad/s","5 rad/s","10 rad/s"],"answer":2,"explanation":"I₁ = ML²/12 = 0.25 kg m² (the beads at the axis add nothing). I₂ = 0.25 + 2 × 0.5 × 0.5² = 0.5 kg m². Conservation of angular momentum: ω = 0.25 × 10/0.5 = 5 rad/s. Putting the beads at distance L instead of L/2 gives 2.5 rad/s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-78","question":"A uniform rod of mass M and length 1.5 m is hinged at one end and carries a point mass M fixed at its other end. It is released from rest in the horizontal position (g = 10 m/s²). Its angular acceleration at the instant of release is:","options":["10 rad/s²","15 rad/s²","5 rad/s²","7.5 rad/s²"],"answer":3,"explanation":"Torque about the hinge = Mg(0.75) + Mg(1.5) = 2.25Mg. I = M(1.5)²/3 + M(1.5)² = 0.75M + 2.25M = 3M. α = 22.5/3 = 7.5 rad/s². 10 rad/s² is the value for the bare rod (3g/2L).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-79","question":"A uniform disc is placed on a rough horizontal floor with its centre moving at v₀ and with no spin. By the time it starts rolling without slipping, the fraction of its initial kinetic energy that has been lost is:","options":["1/3","2/3","1/4","1/2"],"answer":0,"explanation":"Angular momentum about the contact point is conserved: Mv₀R = (3/2)MRv, so v = 2v₀/3. Final K = (3/4)Mv² = (3/4)M(4v₀²/9) = Mv₀²/3, which is 2/3 of ½Mv₀², so 1/3 is lost. 2/3 is the fraction retained.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-rotational-motion-80", "question": "A uniform rod of mass 2 kg and length 1 m rotates on a smooth horizontal table at 4 rad/s about a vertical axis through one end. The tension in the rod at its midpoint is:", "options": ["16 N", "12 N", "8 N", "4 N"], "answer": 1, "explanation": "The part beyond x needs centripetal force T(x) = ∫ₓᴸ (M/L)ω²s ds = (M/L)ω²(L² − x²)/2. At x = L/2: 2 × 16 × (1 − 0.25)/2 = 12 N. 16 N is the tension at the pivot end; 8 N treats the outer half as a point mass at L/2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-81", "question": "A uniform rod 1.2 m long stands vertically on a smooth horizontal floor and is allowed to fall (g = 10 m/s²). When it becomes horizontal, the speed of its centre of mass and the distance its lower end has slid are:", "options": ["6 m/s and 0.6 m", "3 m/s and 0", "3 m/s and 0.6 m", "2√3 m/s and 1.2 m"], "answer": 2, "explanation": "The floor exerts no horizontal force, so the centre of mass falls straight down and the lower end slides L/2 = 0.6 m. At the horizontal position v_cm = ωL/2, so MgL/2 = ½Mv² + ½(ML²/12)(2v/L)² = (2/3)Mv², giving v² = 3gL/4 = 9 and v = 3 m/s. 6 m/s is the speed of the end of a rod hinged at its base.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-rotational-motion-82","question":"A solid sphere is set spinning about a horizontal axis with angular speed ω₀ and placed gently, with no linear velocity, on a rough horizontal floor. By the time it rolls without slipping, the fraction of its initial kinetic energy that has been dissipated is:","options":["2/5","2/7","1/2","5/7"],"answer":3,"explanation":"Angular momentum about the contact point: (2/5)mR²ω₀ = (7/5)mRv, so v = 2ω₀R/7. Initial K = (1/5)mR²ω₀²; final K = (7/10)mv² = (2/35)mR²ω₀², i.e. 2/7 of the initial value. So 5/7 is dissipated; 2/7 is what remains.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-rotational-motion-83", "question": "A uniform solid cylinder rests on a long plank lying on a smooth floor. The plank is pulled so that it accelerates horizontally at 3 m/s², and the cylinder rolls on it without slipping. The acceleration of the cylinder's centre relative to the ground is:", "options": ["1 m/s² in the direction of the plank's acceleration", "3 m/s² in the direction of the plank's acceleration", "2 m/s² opposite to the plank's acceleration", "1 m/s² opposite to the plank's acceleration"], "answer": 0, "explanation": "Friction f (forward) is the only horizontal force: f = ma. Its torque gives α = fR/(½mR²) = 2a/R. No slipping at the contact: a + αR = a₀, so 3a = 3 and a = 1 m/s² forward. Relative to the plank the cylinder goes backward at 2 m/s², which is the trap.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-rotational-motion-84","question":"A spool of mass m (treated as a uniform disc of radius R) has a thread wound on its axle of radius R/2. It stands on a rough horizontal floor, and the thread, leaving the bottom of the axle, is pulled horizontally with force F. The spool rolls without slipping with an acceleration of:","options":["F/(3m), away from the direction of pull","F/(3m), towards the direction of pull","F/m, towards the direction of pull","2F/(3m), towards the direction of pull"],"answer":1,"explanation":"Take torques about the contact point P (I_P = ½mR² + mR² = 3mR²/2). The thread is R − R/2 = R/2 above the floor, so τ = FR/2 = (3mR²/2)α, giving a = αR = F/(3m), towards the pull. (Friction is then F − F/3 = 2F/3 opposing the pull.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-85","question":"A uniform box 1.0 m tall with a square base of side 0.4 m stands on the floor of a truck (coefficient of static friction 0.3). The truck's acceleration is increased slowly from zero. What happens first (g = 10 m/s²)?","options":["The box topples when the acceleration exceeds 4 m/s²","The box topples when the acceleration exceeds 2.5 m/s²","The box slides when the acceleration exceeds 3 m/s²","The box slides when the acceleration exceeds 4 m/s²"],"answer":2,"explanation":"In the truck's frame the pseudo force ma acts at the centre of mass. Sliding needs a > μg = 3 m/s². Toppling about the rear edge needs ma(h/2) > mg(b/2), i.e. a > g b/h = 4 m/s². Sliding happens first, at 3 m/s². It would topple first only if μ > b/h = 0.4.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-rotational-motion-86", "question": "A uniform solid cylinder is released on a plane inclined at 37° (sin 37° = 0.6) with coefficient of friction 0.1 (g = 10 m/s²). The acceleration of its centre is:", "options": ["4.0 m/s²", "6.0 m/s²", "3.47 m/s²", "5.2 m/s²"], "answer": 3, "explanation": "Rolling without slipping would need μ ≥ (1/3) tan 37° = 0.25, but μ = 0.1, so it slips. The friction is kinetic: a = g(sin θ − μ cos θ) = 10(0.6 − 0.08) = 5.2 m/s². The rolling formula (2/3)g sin θ = 4 m/s² misses this hidden condition.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-rotational-motion-87","question":"A uniform rod lies on a smooth horizontal table. A horizontal impulse perpendicular to the rod is applied at a point such that one end of the rod is momentarily at rest just afterwards. The impulse was applied at a distance from that end of:","options":["2L/3","L/2","3L/4","L/6"],"answer":0,"explanation":"With impulse J at a distance x from the centre: v_cm = J/M and ω = Jx/(ML²/12). The far end is at rest if v_cm = ωL/2, giving x = L/6. That point is L/2 + L/6 = 2L/3 from the end that stays at rest. L/6 is the distance from the centre.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-rotational-motion-88", "question": "How many of the following statements about rolling without slipping are correct?\n(A) The angular momentum of a uniform disc rolling on a horizontal floor, about its contact point, is (3/2)MR²ω.\n(B) The kinetic energy of a rolling body equals ½I_Pω², where I_P is its moment of inertia about the contact point.\n(C) For a disc rolling without slipping up an incline with no applied force, the friction acts down the incline.\n(D) Rolling without slipping down a perfectly smooth incline is possible for a sphere released from rest.", "options": ["Only two", "Only one", "Only three", "All four"], "answer": 0, "explanation": "A (½MR²ω + MvR) and B are correct. C is wrong: gravity slows the centre, and friction must act up the slope to slow the spin to match. D is wrong: with no friction there is no torque about the centre, so ω stays zero while the sphere accelerates.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-rotational-motion-89","question":"Two coaxial discs, with moments of inertia 2 kg m² and 3 kg m², spin at 10 rad/s and 5 rad/s in opposite senses. They are pressed together until they rotate as one. The kinetic energy lost is:","options":["15 J","135 J","137.5 J","120 J"],"answer":1,"explanation":"Angular momentum (taking the first disc's sense as positive) = 20 − 15 = 5 kg m²/s, so ω = 5/5 = 1 rad/s. K before = 100 + 37.5 = 137.5 J; after = ½ × 5 × 1² = 2.5 J; lost = 135 J. Adding the angular momenta as if they were in the same sense gives ω = 7 rad/s and a loss of only 15 J.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-rotational-motion-90", "question": "A small uniform solid sphere starts from rest at the top of a large fixed sphere and rolls down the outside without slipping. It leaves the surface when the line from the large sphere's centre to it makes an angle θ with the vertical, where cos θ equals:", "options": ["2/3", "3/7", "10/17", "5/7"], "answer": 2, "explanation": "With R′ = sum of the radii, energy gives (7/10)mv² = mgR′(1 − cos θ). It leaves when mg cos θ = mv²/R′. So (10/7)(1 − cos θ) = cos θ, giving cos θ = 10/17. 2/3 is the answer for a particle that slides without friction.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-rotational-motion-91","question":"A uniform ladder rests against a vertical wall. The coefficient of friction is 0.5 at both the floor and the wall. The least angle the ladder can make with the floor without slipping is:","options":["45°","27°","53°","37°"],"answer":3,"explanation":"Horizontal: N_wall = μN_floor. Vertical: N_floor + μN_wall = W, so N_floor = W/(1 + μ²). Moments about the foot give tan θ = (1 − μ²)/(2μ) = 0.75/1 = 0.75, so θ = 37°. Ignoring friction at the wall gives tan θ = 1/(2μ) = 1, i.e. 45°.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-rotational-motion-92", "question": "A small block on a smooth horizontal table moves in a circle of radius r with kinetic energy K, held by a string that passes through a small hole at the centre. The string is pulled slowly from below until the radius becomes r/2. The work done by the pull is:", "options": ["3K", "K", "4K", "K/4"], "answer": 0, "explanation": "The string's force is central, so angular momentum mvr is conserved: halving r doubles v and makes the kinetic energy 4K. The work done = 4K − K = 3K. 4K is the final kinetic energy, not the work.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-93", "question": "Assertion (A): A solid sphere and a solid cylinder of the same mass and radius roll without slipping at the same speed towards the same rough incline; the sphere rises higher.\nReason (R): At the same speed, the body with the larger value of k²/R² (k = radius of gyration) has the larger total kinetic energy.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "Height h = v²(1 + k²/R²)/2g. The cylinder (k²/R² = 1/2) has more total kinetic energy than the sphere (2/5) at the same speed, so the cylinder rises higher: A is false, R is true.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-rotational-motion-94", "question": "A uniform disc of radius 0.2 m lies flat on a rough horizontal table (μ = 0.3) and is set spinning about its vertical axis at 20 rad/s without moving its centre (g = 10 m/s²). Assuming the normal force is spread uniformly over the disc, it stops spinning after:", "options": ["0.67 s", "1.0 s", "1.5 s", "0.5 s"], "answer": 1, "explanation": "Friction on a ring of radius s gives torque μ(Mg/πR²)(2πs ds)s; integrating, τ = (2/3)μMgR. α = τ/(½MR²) = (4/3)μg/R = (4/3)(3)/0.2 = 20 rad/s², so t = 20/20 = 1.0 s. Taking the friction torque as μMgR gives 0.67 s.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-rotational-motion-95","question":"A disc rolls without slipping on a horizontal floor. At an instant its centre has speed v and acceleration a. The acceleration of the point of the disc in contact with the floor at that instant is:","options":["Zero","a, along the floor","v²/R, directed towards the centre","√(a² + v⁴/R²)"],"answer":2,"explanation":"Relative to the centre the contact point has a tangential acceleration αR = a backward and a centripetal acceleration v²/R upward. Adding the centre's acceleration a forward, the horizontal parts cancel, leaving v²/R towards the centre. Its velocity is zero, but its acceleration is not.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-rotational-motion-96","question":"The moment of inertia of a given rigid body does NOT depend on:","options":["how its mass is distributed about the axis","the position of the axis","the orientation of the axis","its angular velocity"],"answer":3,"explanation":"I = Σmr² depends only on the masses and their distances from the chosen axis. It is a property of the body and axis, not of how fast the body is spinning.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-rotational-motion-97","question":"A uniform semicircular plate of mass M and radius R (half of a disc) is rotated about the axis through the centre of the original full circle, perpendicular to its plane. Its moment of inertia about this axis is:","options":["MR²","MR²/4","MR²/2","3MR²/2"],"answer":2,"explanation":"Every element of the half-disc lies at the same distances from this axis as in a full disc, and I scales with mass in the same way. So the half-disc of mass M has I = MR²/2, the same formula as a full disc of mass M.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-rotational-motion-98","question":"Four identical thin uniform rods, each of mass m and length a, form a square frame. Its moment of inertia about an axis through one corner, perpendicular to the plane of the square, is:","options":["4ma²/3","10ma²/3","8ma²/3","2ma²"],"answer":1,"explanation":"About the centre: each rod has ma²/12 + m(a/2)², so I_c = 4 × ma²/3 = 4ma²/3. The corner is a/√2 from the centre, so by the parallel-axis theorem I = 4ma²/3 + 4m(a²/2) = 10ma²/3.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-99","question":"A uniform 2 kg rod, hinged smoothly at its lower end, is released from rest in the vertical position and falls over. At the instant it is horizontal, the magnitude of the force exerted by the hinge on it is (g = 10 m/s²):","options":["5√37 N ≈ 30.4 N","30 N","5 N","20 N"],"answer":0,"explanation":"Energy gives ω² = 3g/L, so the centripetal force at the CM is Mω²(L/2) = 3Mg/2 = 30 N along the rod. Torque gives α = 3g/2L, so a_CM = 3g/4 downward and the vertical hinge force is Mg − 3Mg/4 = 5 N. Resultant = √(30² + 5²) = 5√37 ≈ 30.4 N.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-100","question":"A uniform rod of mass 0.6 kg and length 1 m hangs vertically from a smooth hinge at its top end. A 0.2 kg lump of clay moving horizontally strikes its lower end and sticks. The minimum speed of the clay for the rod to swing up to the horizontal is (g = 10 m/s²):","options":["10 m/s","5 m/s","√50 m/s","20 m/s"],"answer":0,"explanation":"Angular momentum about the hinge: 0.2v × 1 = Iω with I = 0.6/3 + 0.2 = 0.4 kg m², so ω = v/2. To reach the horizontal, ½Iω² = (0.6 × 0.5 + 0.2 × 1) × 10 = 5 J, so 0.2ω² = 5, ω = 5 rad/s and v = 10 m/s. Energy is not conserved in the sticking impact.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-101","question":"A solid sphere is launched along a rough horizontal floor (μ = 0.2) with a speed of 7 m/s and no initial rotation (g = 10 m/s²). The distance it covers before it starts rolling without slipping is:","options":["12.25 m","5 m","7 m","6 m"],"answer":3,"explanation":"Angular momentum about the contact line is conserved: mv₀R = mvR + (2/5)mR²(v/R), so v = 5v₀/7 = 5 m/s. Friction decelerates the centre at μg = 2 m/s², so t = 1 s and s = 7 × 1 − ½ × 2 × 1² = 6 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-102","question":"A 2 kg uniform disc is set sliding (without rotation) at 6 m/s on a rough horizontal floor, standing on its rim in a vertical plane. By the time it rolls without slipping, the heat produced by friction is:","options":["24 J","36 J","12 J","4 J"],"answer":2,"explanation":"Angular momentum about the contact line: mv₀R = mvR + ½mR²(v/R), so v = 2v₀/3 = 4 m/s. Final KE = ¾mv² = 0.75 × 2 × 16 = 24 J. Heat = 36 − 24 = 12 J.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-103","question":"A billiard ball (uniform solid sphere of radius R) is struck so that it starts sliding forward on a rough table with speed v₀ and with backspin ω₀. It finally comes to rest completely (no translation, no rotation). Then ω₀ must be:","options":["2v₀/5R","5v₀/2R","v₀/R","7v₀/2R"],"answer":1,"explanation":"Friction acts through the contact point, so angular momentum about any point on the table line is conserved. Initially L = mv₀R − (2/5)mR²ω₀ (backspin opposes). For the final state of rest L = 0, so ω₀ = 5v₀/2R.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-104","question":"A horizontal force F is applied to the TOP of a uniform solid cylinder of mass M that rolls without slipping on a rough horizontal floor. The static friction on the cylinder from the floor is:","options":["F/3, opposite to F","F/3, in the same direction as F","zero","F/2, opposite to F"],"answer":1,"explanation":"Let friction f act forward. F + f = Ma and (F − f)R = ½MR²(a/R), so F − f = Ma/2. Adding: 2F = 3Ma/2, a = 4F/3M, and f = Ma − F = F/3 > 0, i.e. forward, along F.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-105","question":"A uniform solid sphere of radius R rests on a rough horizontal floor. A horizontal force is applied in the vertical plane through its centre at a height h above the FLOOR. For the sphere to roll without slipping with no friction at all, h must be:","options":["7R/5","R","2R","6R/5"],"answer":0,"explanation":"Without friction: F = Ma and F(h − R) = (2/5)MR²(a/R). Dividing gives h − R = 2R/5, so h = 7R/5 (the 'centre of percussion' height).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-106","question":"A thin hollow sphere rolls without slipping on a level floor. The fraction of its total kinetic energy that is rotational is:","options":["3/5","2/7","1/3","2/5"],"answer":3,"explanation":"With I = (2/3)MR², rotational KE = (1/3)Mv² and translational = (1/2)Mv². Fraction = (1/3)/(1/2 + 1/3) = 2/5. (2/7 applies to a solid sphere.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-rotational-motion-107","question":"Disc A (moment of inertia I, radius R) spins at ω₀ about a fixed axle. Disc B (also moment of inertia I, but radius 2R), initially at rest on its own fixed parallel axle, is brought up so that their rims press together. Once the rims stop slipping, the angular speed of A is:","options":["2ω₀/3","ω₀/2","4ω₀/5","2ω₀/5"],"answer":2,"explanation":"Angular momentum is NOT conserved, because the axles exert forces. Use angular impulse of the rim friction J: I(ω₀ − ω_A) = JR and Iω_B = J(2R). No slipping: ω_A R = ω_B(2R). Solving: ω_B = 2ω₀/5 and ω_A = 4ω₀/5.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-108","question":"A wheel of radius R rolls without slipping at a constant speed v on level ground. For the point of the rim that is momentarily in contact with the ground:","options":["its velocity is zero and its acceleration is v²/R, directed along the ground","both its velocity and acceleration are zero","its velocity is zero but its acceleration is v²/R, directed towards the centre","its velocity is v and its acceleration is zero"],"answer":2,"explanation":"With constant v, the centre is unaccelerated, and every rim point has acceleration ω²R = v²/R towards the centre. At the contact point the velocities v (translation) and ωR (rotation) cancel, but the acceleration does not: it points straight up, which is why the point lifts off the ground.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-109","question":"A 2 m rod slides with its upper end on a smooth vertical wall and lower end on a smooth floor. When the rod makes 37° with the floor (sin 37° = 0.6), the lower end moves away from the wall at 3 m/s. The speed of the rod's midpoint at this instant is:","options":["3 m/s","2.5 m/s","1.5 m/s","4 m/s"],"answer":1,"explanation":"The instantaneous centre of rotation is where perpendiculars to the end velocities meet: 1.2 m above the bottom end. So ω = 3/1.2 = 2.5 rad/s. The midpoint is always L/2 = 1 m from this point (the corner of a rectangle with the rod as diagonal), so its speed is 2.5 × 1 = 2.5 m/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-110","question":"A motor applies a constant torque to a flywheel of moment of inertia 0.5 kg m², taking it from rest to 20 rad/s in 5 s. The power delivered by the motor at the end of this interval is:","options":["40 W","20 W","100 W","10 W"],"answer":0,"explanation":"α = 20/5 = 4 rad/s², so τ = Iα = 2 N m. Power P = τω, which grows linearly; at 20 rad/s it is 40 W. 20 W is only the average power (100 J of KE in 5 s).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-111","question":"A uniform 0.9 m rod hangs vertically from a frictionless hinge at its top. A sharp horizontal blow is to be struck on it so that the hinge exerts NO impulsive horizontal force. The blow must be struck at a distance from the hinge of:","options":["0.3 m","0.45 m","0.9 m","0.6 m"],"answer":3,"explanation":"With impulse J at distance x: linear impulse J = Mv_cm = Mω(L/2) and angular impulse Jx = (ML²/3)ω. Dividing: x = (L²/3)/(L/2) = 2L/3 = 0.6 m, the centre of percussion.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-112","question":"A uniform 6 m plank of mass 30 kg rests on two supports placed 1.5 m from each end. A 60 kg man walks out along the plank beyond one support. The plank begins to tip when he is beyond that support by:","options":["1 m","1.5 m","0.5 m","0.75 m"],"answer":3,"explanation":"Tipping occurs about the nearer support when the other support's reaction becomes zero. Torques about that support: 60g·x = 30g × 1.5 (the plank's CM is 1.5 m on the other side), so x = 0.75 m.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-rotational-motion-113","question":"A uniform disc of mass 2 kg and radius 0.5 m rolls without slipping at 4 m/s on level ground. Its angular momentum about any fixed point on the ground (in the plane of the disc) is:","options":["4 kg m²/s","2 kg m²/s","6 kg m²/s","8 kg m²/s"],"answer":2,"explanation":"L = L_spin + L_orbital = I_cm ω + Mv × (height of CM) = ½MR(v) + MvR = (3/2)MRv = 1.5 × 2 × 0.5 × 4 = 6 kg m²/s, the same for every point on the ground line.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-114","question":"The moment of inertia of a thin uniform square plate of mass M and side a about one of its DIAGONALS is:","options":["Ma²/6","Ma²/12","Ma²/24","Ma²/3"],"answer":1,"explanation":"About the perpendicular axis through the centre, I_z = Ma²/6. By symmetry the two diagonals have equal moments of inertia, and by the perpendicular-axis theorem I_d + I_d = I_z, so I_d = Ma²/12 (the same as about a line through the centre parallel to a side).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-115","question":"A 60 kg man stands at the rim of a horizontal uniform disc (mass 120 kg, radius 2 m) that can turn freely about a vertical axis; everything is at rest. He walks once round the rim until he is back at the same point OF THE DISC. Through what angle has the disc turned?","options":["180°","360°","90°","120°"],"answer":0,"explanation":"Total angular momentum stays zero, so I_man θ_man = I_disc θ_disc (opposite senses). Here I_man = 60 × 4 = 240 kg m² and I_disc = ½ × 120 × 4 = 240 kg m², so the angles are equal. They add to one relative revolution (2π), so the disc turns π rad = 180°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-116","question":"A solid sphere rolls without slipping at 7 m/s on a level floor and then runs up a perfectly SMOOTH (frictionless) curved ramp (g = 10 m/s²). The maximum height it reaches is:","options":["2.45 m","3.43 m","1.75 m","4.9 m"],"answer":0,"explanation":"On a frictionless ramp no torque acts about the CM, so the spin (and its rotational KE) stays unchanged. Only the translational KE ½mv² converts to height: h = v²/2g = 49/20 = 2.45 m. On a rough ramp it would reach 7v²/10g = 3.43 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-117","question":"Particles of 1 kg and 2 kg are joined by a light rigid rod 3 m long and rest on a smooth horizontal table. The 1 kg particle is suddenly given a velocity of 6 m/s perpendicular to the rod. The tension in the rod in the subsequent motion is:","options":["4 N","12 N","24 N","8 N"],"answer":3,"explanation":"The CM (1 m from the 2 kg mass, 2 m from the 1 kg mass) moves uniformly, while the rod rotates about it with ω = v_rel/L = 6/3 = 2 rad/s. The rod supplies the centripetal force: T = 1 × 2² × 2 = 8 N (= 2 × 2² × 1).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-118","question":"A uniform solid sphere rolling without slipping at speed v₀ hits an identical sphere at rest head-on. The impact is elastic and brief, and friction from the floor is negligible during the impact. After both spheres again roll without slipping, the speed of the first sphere is:","options":["5v₀/7","zero","2v₀/7","v₀/2"],"answer":2,"explanation":"During the brief impact the translational velocities exchange, but the spins do not: sphere 1 is left with zero speed and spin v₀/R. Friction then acts, conserving angular momentum about the contact line: (2/5)mR²(v₀/R) = (7/5)mRv, so v = 2v₀/7. (Sphere 2 ends at 5v₀/7.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-119","question":"Two bodies have equal angular momenta about their fixed axes, but body P has the smaller moment of inertia. Which statement is correct?","options":["Q has the greater rotational kinetic energy","P has the greater rotational kinetic energy","Their rotational kinetic energies are equal","P has the smaller angular speed"],"answer":1,"explanation":"K = L²/2I, so for equal L the body with the smaller I has the larger kinetic energy (and also the larger angular speed ω = L/I).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-rotational-motion-120","question":"A 7 kg uniform solid sphere rolls without slipping down a plane inclined at 30° (g = 10 m/s²). The friction force acting on it is:","options":["10 N, down the incline","10 N, up the incline","35 N, up the incline","25 N, up the incline"],"answer":1,"explanation":"a = g sin θ/(1 + 2/5) = (5/7)g sin θ. Then f = mg sin θ − ma = (2/7)mg sin θ = (2/7) × 7 × 10 × 0.5 = 10 N, acting up the slope to produce the rolling torque.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-121","question":"A thick uniform hollow cylinder (a tube) of mass 2 kg has inner radius 0.1 m and outer radius 0.3 m. Its moment of inertia about its own axis is:","options":["0.1 kg m²","0.08 kg m²","0.2 kg m²","0.09 kg m²"],"answer":0,"explanation":"For a thick tube I = M(R₁² + R₂²)/2 (obtained by subtracting the missing core from a solid cylinder of the same density). I = 2(0.01 + 0.09)/2 = 0.1 kg m². 0.08 wrongly uses (R₂² − R₁²).","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-rotational-motion-122","question":"A uniform pole 2.7 m long stands vertically on rough ground. It is nudged and falls over, its lower end not slipping. The speed of its top end just before it hits the ground is (g = 10 m/s²):","options":["18 m/s","√54 m/s","√27 m/s","9 m/s"],"answer":3,"explanation":"The pole rotates about its fixed base: Mg(L/2) = ½(ML²/3)ω², so ω² = 3g/L. The top moves at ωL = √(3gL) = √81 = 9 m/s, faster than the √(2gL) ≈ 7.3 m/s of a freely falling body.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-123","question":"Which statement about the plane motion of a rigid body is correct?","options":["Points farther from the centre of mass have larger angular velocities","The angular velocity depends on the reference point chosen on the body","The angular velocity of the body is the same about every point of the body","A body that is translating can have different angular velocities about different points"],"answer":2,"explanation":"For a rigid body, the relative velocity of any two points B and A is ω × r_BA with one and the same ω. So the angular velocity is a property of the whole body; only linear velocities vary from point to point.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-rotational-motion-124","question":"A uniform rod 1.5 m long, hinged smoothly at its lower end, is held at 60° above the horizontal and released (g = 10 m/s²). Its angular acceleration just after release is:","options":["8.66 rad/s²","10 rad/s²","5 rad/s²","2.5 rad/s²"],"answer":2,"explanation":"τ = Mg(L/2)cos 60° about the hinge and I = ML²/3. α = 3g cos θ/2L = 3 × 10 × 0.5/3 = 5 rad/s². The cosine appears because the lever arm of the weight is the horizontal distance.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-rotational-motion-125","question":"A uniform rod spins with angular speed ω, first about a perpendicular axis through one end and then (with the same ω) about a parallel axis through its centre. The ratio of the first kinetic energy to the second is:","options":["2","4","1/4","3"],"answer":1,"explanation":"K = ½Iω² with I_end = ML²/3 and I_centre = ML²/12. The ratio is (1/3)/(1/12) = 4.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-rotational-motion-126","question":"A uniform cube of edge 0.6 m slides without rotating at 4 m/s on a smooth floor and its leading bottom edge hits a small fixed ridge, about which it starts to turn. The angular speed of the cube just after the impact is:","options":["5 rad/s","6.67 rad/s","10 rad/s","3.33 rad/s"],"answer":0,"explanation":"The impulsive force acts at the edge, so angular momentum about that edge is conserved: Mv(a/2) = I_edge ω with I_edge = (2/3)Ma² (= Ma²/6 + Ma²/2). Hence ω = 3v/4a = 12/2.4 = 5 rad/s.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-127","question":"A 2 kg uniform solid sphere rolls without slipping at 5 m/s. Its total kinetic energy is:","options":["45 J","25 J","10 J","35 J"],"answer":3,"explanation":"K = ½mv²(1 + k²/R²) = ½ × 2 × 25 × (1 + 2/5) = 25 × 1.4 = 35 J (25 J translational, 10 J rotational).","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-rotational-motion-128","question":"A disc of radius 0.2 m moves on a floor with its centre moving forward at 4 m/s while it spins at 10 rad/s in the sense of forward rolling. The point about which it is instantaneously rotating lies:","options":["0.4 m above the centre","at the contact point","0.2 m above the centre","0.4 m below the centre, i.e. 0.2 m below the floor surface"],"answer":3,"explanation":"The instantaneous axis is where the translational velocity v is cancelled by the rotational velocity ωy, i.e. at y = v/ω = 0.4 m below the centre (for forward-sense spin). Since ωR = 2 m/s < v, the disc is skidding forward and the point lies below the floor.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-rotational-motion-129","question":"A uniform 2 kg beam is hinged to a wall at one end and kept horizontal by a light string from its other end to a point on the wall above the hinge; the string makes 30° with the beam (g = 10 m/s²). The tension in the string is:","options":["40 N","10 N","20 N","11.5 N"],"answer":2,"explanation":"Torques about the hinge: T sin 30° × L = mg × L/2, so T = mg/(2 sin 30°) = mg = 20 N. The hinge force supplies the rest of the balance.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
